/** New reconstruction: opt-in state model, no automatic local/game mutation. */
export function createCloudAccountModel({client,bridge,journal,enabled=false,now=()=>Date.now()}){
 const saved=journal.read();let epoch=0,committingRestore=false;
 let state={phase:enabled?(saved.pending?'uncertain':'idle'):'disabled',account:null,slots:[],slotsLoaded:false,review:null,pending:saved.pending,blocked:saved.blocked,message:saved.blocked?'An unreadable recovery note is kept. Uploads are blocked.':saved.pending?'An earlier upload needs verification.':'Optional cloud saves.',loginURL:''};
 // The host resets its old import UI during a synchronous restore. That reset
 // must not relabel an already accepted load as cancelled; no await occurs here.
 const listeners=new Set();
 const snapshot=()=>({...state,slots:state.slots.map(x=>({...x})),kinds:bridge.kinds()});
 const emit=()=>{for(const listener of listeners)listener(snapshot());};
 const set=values=>{state={...state,...values};emit();};
 const current=id=>{if(id!==epoch)throw new Error('Cloud action was superseded');};
 const begin=(phase,review=null)=>{if(!enabled)throw new Error('Cloud accounts are disabled');const id=++epoch;set({phase,review,loginURL:'',message:'Checking cloud account…'});return id;};
 const bind=account=>set({account:{id:account.id,expiresAt:account.expiresAt},...(state.account?.id!==account.id?{slots:[],slotsLoaded:false}: {})});
 const fail=(id,error)=>{if(id!==epoch)return;const signedOut=error?.status===401||error?.status===403||error?.code==='sign-in-required'||error?.code==='account-changed';set({phase:state.pending?'uncertain':signedOut?'guest':'error',review:null,loginURL:'',...(signedOut?{account:null,slots:[],slotsLoaded:false}:{}),message:state.pending?'The upload outcome is unknown. Sign into its original account if needed, then check the saved copy.':error?.message||'Cloud service unavailable.'});};
 const requireSafe=()=>{if(state.pending||state.blocked)throw new Error('Resolve the previous recovery note before a new upload');};
 const addMetadata=record=>{const metadata={...record};delete metadata.document;return [...state.slots.filter(x=>x.kind!==record.kind||x.slot!==record.slot),metadata];};
 return Object.freeze({
  snapshot,
  sync(){emit();},
  subscribe(listener){listeners.add(listener);listener(snapshot());return()=>listeners.delete(listener);},
  cancelReview(){if(committingRestore)return;epoch++;set({review:null,loginURL:'',phase:state.pending?'uncertain':state.account?'ready':'guest',message:'Cloud review cancelled. Your game is unchanged.'});},
  leave(){epoch++;set({review:null,loginURL:'',phase:enabled?(state.pending?'uncertain':state.account?'ready':'idle'):'disabled'});},
  async refresh(){if(!enabled)return;const id=begin('loading');set({slotsLoaded:false});try{const account=await client.account();current(id);bind(account);const slots=await client.list();current(id);set({slots,slotsLoaded:true,phase:state.pending?'uncertain':'ready',message:state.pending?'An earlier upload still needs verification.':'Choose a cloud slot. Local play is unchanged.'});}catch(error){fail(id,error);}},
  async login(){const id=begin('loading');try{const loginURL=await client.login();current(id);set({loginURL,phase:state.pending?'uncertain':state.account?'ready':'guest',message:'Finish signing in with Google, then return here. Keep this game tab open.'});}catch(error){fail(id,error);}},
  async logout(){const id=begin('loading');try{await client.logout();current(id);set({account:null,slots:[],slotsLoaded:false,phase:state.pending?'uncertain':'guest',message:state.pending?'Signed out. The recovery note is kept; sign into the original account to verify it.':'Signed out. Local play is unchanged.'});}catch(error){fail(id,error);}},
  async prepareUpload(kind,slot){requireSafe();const captured=bridge.capture(kind),id=begin('loading');try{const account=await client.account();current(id);bind(account);const remote=await client.download(kind,slot);current(id);if(!bridge.matches(captured))throw new Error('The game or import choice changed. Review again.');set({phase:'review',review:{type:'upload',accountID:account.id,kind,slot,captured,remote,expectedRevision:remote?.revision??0},message:remote?'Replace this cloud slot with the captured local checkpoint?':'Upload this checkpoint to the empty cloud slot?'});}catch(error){fail(id,error);}},
  async prepareRestore(kind,slot){bridge.beginRestore?.();const captured=bridge.capture(kind),id=begin('loading');try{const account=await client.account();current(id);bind(account);const remote=await client.download(kind,slot);current(id);if(!remote)throw new Error('This cloud slot is empty');if(!bridge.matches(captured))throw new Error('The game or import choice changed. Review again.');set({phase:'review',review:{type:'restore',accountID:account.id,kind,slot,captured,remote,plan:bridge.planRestore?.(kind,remote.document)??null},message:kind==='wayfarer'?'Replace the current charter session. Its live field restarts. Export the current charter first if needed.':'Review the cloud copy and choose how to load it. Nothing changes until you choose.'});}catch(error){fail(id,error);}},
  async confirm(choice=null,expectedReview=state.review){const review=state.review;if(!review||review!==expectedReview)throw new Error('Review a cloud action first');if(review.plan&&!review.plan.choices.some(option=>option.id===choice&&!option.disabled))throw new Error('Choose one of the reviewed load options.');const id=begin('loading',review);try{const account=await client.account();current(id);bind(account);if(account.id!==review.accountID)throw new Error('The signed-in account changed. Review again.');if(!bridge.matches(review.captured))throw new Error('The game or import choice changed. Review again.');if(review.type==='restore'){const latest=await client.download(review.kind,review.slot);current(id);if(!latest||latest.revision!==review.remote.revision||latest.document!==review.remote.document)throw new Error('The cloud slot changed. Download a new preview.');if(!bridge.matches(review.captured))throw new Error('A newer local import choice must be kept.');let result;committingRestore=true;try{result=bridge.restore(review.kind,latest.document,review.captured,choice);}finally{committingRestore=false;}if(id===epoch)set({phase:'ready',review:null,message:review.kind==='wayfarer'?'The current charter session was replaced.':result?.restored?review.kind==='decks'?'Saved decks added. Open the deck workshop to compare and apply them. No cards were equipped.':'Cloud checkpoint loaded. Existing device saves and the cloud copy were kept.':'Finish the game’s staged import review.'});return;}
    requireSafe();const note=journal.save({schema:'castledecks-cloud-upload-1',accountID:account.id,kind:review.kind,slot:review.slot,expectedRevision:review.expectedRevision,document:review.captured.document,createdAt:now()});set({pending:note,phase:'writing',review:null,message:'Uploading the captured checkpoint…'});
    try{const result=await client.upload(note.kind,note.slot,note.document,note.expectedRevision);current(id);journal.clear(note);set({pending:null,phase:'ready',review:null,slots:addMetadata(result),message:'Cloud copy verified.'});}catch(error){if(id!==epoch)return;if(error?.uncertain||![400,401,403,404,409,413,415,428,429].includes(error?.status)){set({phase:'uncertain',message:'The upload may have committed. Check the saved copy before doing anything else.'});}else{journal.clear(note);set({pending:null});throw error;}}
   }catch(error){fail(id,error);}},
  async reconcile(){if(!state.pending)throw new Error('No upload needs verification');const note=state.pending,id=begin('loading');try{const account=await client.account();current(id);bind(account);if(account.id!==note.accountID){set({phase:'uncertain',message:'Sign into the same account that started this upload, then check again.'});return;}const remote=await client.download(note.kind,note.slot);current(id);if(remote&&remote.revision>note.expectedRevision){journal.clear(note);set({pending:null,phase:'ready',slots:addMetadata(remote),message:remote.document===note.document?'The current cloud copy matches the captured upload.':'This cloud slot has a newer different copy. Review before any new upload.'});}else{set({phase:'uncertain',message:'The saved copy has not verified this upload. Keep the recovery note; do not retry automatically.'});}}catch(error){fail(id,error);}}
 });
}
